import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, invoiceTotals } from '../src/totals.js';

describe('lineTotal', () => {
  test('calculates qty times unitPrice', () => {
    const line = { qty: 5, unitPrice: 8500 };
    assert.equal(lineTotal(line), 42500);
  });

  test('handles single unit', () => {
    const line = { qty: 1, unitPrice: 1000 };
    assert.equal(lineTotal(line), 1000);
  });

  test('handles large quantities', () => {
    const line = { qty: 500, unitPrice: 1000 };
    assert.equal(lineTotal(line), 500000);
  });
});

describe('invoiceTotals', () => {
  test('calculates subtotal and total for a single line', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, 8925);
    assert.equal(totals.voucher, 0);
    assert.equal(totals.total, 51425);
  });

  test('calculates subtotal and total for multiple lines', () => {
    const invoice = {
      lines: [
        { qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 },
        { qty: 2, unitPrice: 5000, discountPercent: 0, vatRate: 9 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 52500);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, 10395);
    assert.equal(totals.total, 62895);
  });

  test('handles empty invoice', () => {
    const invoice = { lines: [] };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 0);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, 0);
    assert.equal(totals.voucher, 0);
    assert.equal(totals.total, 0);
  });

  test('calculates discount for a single line with 10% discount', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 10, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500);
    assert.equal(totals.discount, 4250);
    assert.equal(totals.vat, 8032.5);
    assert.equal(totals.total, 46282.5);
  });

  test('calculates discount with decimal percentage', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 2.5, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500);
    assert.equal(totals.discount, 1062.5);
    assert.equal(totals.vat, 8703.75);
    assert.equal(totals.total, 50141.25);
  });

  test('calculates total discount across multiple lines', () => {
    const invoice = {
      lines: [
        { qty: 5, unitPrice: 8500, discountPercent: 10, vatRate: 21 },
        { qty: 2, unitPrice: 5000, discountPercent: 5, vatRate: 9 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 52500);
    assert.equal(totals.discount, 4750);
    assert.equal(totals.vat, 9078.75);
    assert.equal(totals.total, 56828.75);
  });

  test('clamps total at 0 when discount exceeds subtotal', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 200, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500);
    assert.equal(totals.discount, 85000);
    assert.equal(totals.vat, 0);
    assert.equal(totals.total, 0);
  });

  test('handles mixed discounted and non-discounted lines', () => {
    const invoice = {
      lines: [
        { qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 },
        { qty: 2, unitPrice: 5000, discountPercent: 10, vatRate: 9 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 52500);
    assert.equal(totals.discount, 1000);
    assert.equal(totals.vat, 10161);
    assert.equal(totals.total, 61661);
  });

  test('calculates VAT on line after discount', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 10, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    const lineSubtotal = 42500;
    const lineDiscount = lineSubtotal * 0.1;
    const lineAfterDiscount = lineSubtotal - lineDiscount;
    const expectedVat = lineAfterDiscount * 0.21;
    assert.equal(totals.vat, expectedVat);
  });

  test('calculates VAT with 21% rate', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.vat, 8925);
  });

  test('calculates VAT with 9% rate', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 5000, discountPercent: 0, vatRate: 9 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.vat, 900);
  });

  test('calculates VAT with 0% rate', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.vat, 0);
  });

  test('sums VAT across multiple lines', () => {
    const invoice = {
      lines: [
        { qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 },
        { qty: 2, unitPrice: 5000, discountPercent: 0, vatRate: 9 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.vat, 10395);
  });

  test('rounds VAT per line before summing', () => {
    const invoice = {
      lines: [
        { qty: 3, unitPrice: 333, discountPercent: 0, vatRate: 21 },
        { qty: 3, unitPrice: 333, discountPercent: 0, vatRate: 21 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.vat, 420);
  });

  test('calculates VAT on amount after discount and tier discount', () => {
    const invoice = {
      lines: [
        { qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 },
        { qty: 2, unitPrice: 5000, discountPercent: 5, vatRate: 9 },
      ],
    };
    const totals = invoiceTotals(invoice);
    const line1Subtotal = 42500;
    const line1Vat = line1Subtotal * 0.21;
    const line2Subtotal = 10000;
    const line2Discount = line2Subtotal * 0.05;
    const line2AfterDiscount = line2Subtotal - line2Discount;
    const line2Vat = line2AfterDiscount * 0.09;
    assert.equal(totals.vat, line1Vat + line2Vat);
  });

  test('includes voucher in total calculation', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
      voucher: { amount: 5000 },
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500);
    assert.equal(totals.voucher, 5000);
    assert.equal(totals.total, 46425);
  });

  test('returns 0 voucher for invoice without voucher', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.voucher, 0);
  });

  test('clamps total at 0 when voucher exceeds subtotal + vat', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
      voucher: { amount: 100000 },
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.total, 0);
  });

  test('calculates correct total with voucher applied', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
      voucher: { amount: 10000 },
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500);
    assert.equal(totals.vat, 8925);
    assert.equal(totals.voucher, 10000);
    assert.equal(totals.total, 41425);
  });
});

