    const invoice = {
      lines: [
        { qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 },
        { qty: 2, unitPrice: 5000, discountPercent: 0, vatRate: 9 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.vat, 10395);
  });

  test('rounds VAT per line before summing', () => {
    const invoice = {
      lines: [
        { qty: 3, unitPrice: 333, discountPercent: 0, vatRate: 21 },
        { qty: 3, unitPrice: 333, discountPercent: 0, vatRate: 21 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.vat, 420);
  });

  test('calculates VAT on amount after discount and tier discount', () => {
    const invoice = {
      lines: [
        { qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 },
        { qty: 2, unitPrice: 5000, discountPercent: 5, vatRate: 9 },
